mapper.select:
SELECT source_event_id AS eventId,request_sha256 AS requestSha256,status,affected_lines AS affectedLines,
       applied_at AS appliedAt
FROM inv_lot_command WHERE tenant_id=#{tenantId} AND source_event_id=#{eventId}

SELECT MIN(movement_type) AS movementType,ABS(SUM(quantity_delta)) AS absoluteQuantity
FROM inv_stock_ledger
WHERE tenant_id=#{tenantId} AND source_event_id=#{eventId} AND source_line_id=#{sourceLineId}
  AND warehouse_id=#{warehouseId} AND sku_id=#{skuId}
GROUP BY source_event_id,source_line_id,warehouse_id,sku_id

SELECT  FROM inv_lot_identity i
JOIN inv_lot_balance b ON b.tenant_id=i.tenant_id AND b.lot_id=i.lot_id
LEFT JOIN inv_lot_expiry_projection p ON p.tenant_id=i.tenant_id AND p.lot_id=i.lot_id
WHERE i.tenant_id=#{tenantId} AND i.warehouse_id=#{warehouseId} AND i.sku_id=#{skuId}
  AND b.on_hand_quantity>0 AND i.expiry_date>=#{businessDate}
ORDER BY i.expiry_date ASC,i.received_date ASC,i.lot_id ASC LIMIT #{limit} FOR UPDATE

mapper.update:
UPDATE inv_lot_balance SET on_hand_quantity=#{onHandQuantity},last_ledger_sequence=#{lastLedgerSequence},
  record_version=record_version+1,updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND lot_id=#{lotId} AND record_version=#{expectedVersion}

mapper.select:
SELECT  FROM inv_lot_identity i
JOIN inv_lot_balance b ON b.tenant_id=i.tenant_id AND b.lot_id=i.lot_id
LEFT JOIN inv_lot_expiry_projection p ON p.tenant_id=i.tenant_id AND p.lot_id=i.lot_id
WHERE i.tenant_id=#{tenantId} AND i.store_id=#{storeId} AND i.warehouse_id=#{warehouseId}
  AND b.on_hand_quantity>0
ORDER BY i.sku_id,i.expiry_date,i.received_date,i.lot_id LIMIT #{limit}

SELECT  FROM inv_lot_identity i
JOIN inv_lot_balance b ON b.tenant_id=i.tenant_id AND b.lot_id=i.lot_id
LEFT JOIN inv_lot_expiry_projection p ON p.tenant_id=i.tenant_id AND p.lot_id=i.lot_id
WHERE i.tenant_id=#{tenantId} AND i.store_id=#{storeId} AND i.warehouse_id=#{warehouseId}
  AND i.sku_id=#{skuId}
ORDER BY i.expiry_date,i.received_date,i.lot_id LIMIT #{limit}

SELECT COALESCE(SUM(quantity_delta),0) AS ledgerQuantity,
  COALESCE(MAX(ledger_sequence),0) AS lastLedgerSequence
FROM inv_lot_ledger WHERE tenant_id=#{tenantId} AND lot_id=#{lotId}

mapper.update:
UPDATE inv_lot_balance SET on_hand_quantity=#{onHandQuantity},
  last_ledger_sequence=#{lastLedgerSequence},record_version=record_version+1,updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND lot_id=#{lotId}

